('8322dbe7-e0cd-bc6f-fbbf-f718183c1dfa', 'd3445ff9-781e-06c9-8934-9befb767ef5c', 1, NULL, 'Imported package content', 'Imported from 07 Days Golden Triangle Tour for Website.docx', 'manual'::revision_save_type, '{"header": {"title": "07 Days Delhi, Agra & Jaipur Tour Package", "subtitle": "Delhi, Agra & Jaipur", "tour_code": "DR078", "duration_label": "06 Night / 07 Days", "alternate_titles": []}, "client": {"title": "Mr", "client_name": "Website Package", "email": null, "email2": null, "phone": null, "adults": 2, "children_5_12": 0, "children_below_5": 0, "rooms": 1, "extra_beds": 0, "travel_date": null, "food_preference": null, "special_requests": null}, "days": [{"day_uuid": "05e57053-6f2c-3543-b2d2-a051ac294e93", "day_number": 1, "day_title": "Arrival in Delhi", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "You are going to visit Delhi, so assume yourself in the vibrant energy of Delhi, a wonderful city where antique history and modernism flawlessly blend. Discover majestic monuments, busy markets, and a different culinary scene.\nUpon your arrival at the Railway Station/Airport in Delhi, our representative will warmly welcome you. You will then be escorted to your hotel for check-in. Delhi, being India''s capital city, is renowned for its tourist attractions, diverse cuisine, and bustling markets. Take the day to explore on your own.\nOvernight stay at a hotel in Delhi.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Delhi", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": false, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "cf129f34-9ec3-e5d4-9ad2-93cd8c16702c", "day_number": 2, "day_title": "Delhi Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After a hearty breakfast, embark on a tour to explore the iconic attractions of Delhi:\nRed Fort - A symbol of India''s rich history.\nPurana Quila (Old Fort) - Ancient fortress with tales.\nJama Masjid - Magnificent mosque of Delhi.\nQutub Minar - Tower of victory.\nIndia Gate - Memorial honoring soldiers.\nChandni Chowk - Lively market street.\nLakshmi Narayan Temple - Spiritual haven.\nOvernight stay at a hotel in Delhi.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Delhi", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "ba892f10-f86a-83bf-aab2-623d935d6674", "day_number": 3, "day_title": "Delhi to Agra", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Agra is home to the wonderful Taj Mahal, Agra catches attention of visitors with its rich Mughal tradition. Explore grand forts, beautiful gardens, and everlasting architectural wonders.\nAfter breakfast, journey to Agra. Upon arrival and check-in at the hotel, relax before exploring:\nTaj Mahal - Timeless symbol of love.\nAgra Fort - Mughal architectural gem.\nItimad-Ud-Daulah (Baby Taj) - Elegant marble mausoleum.\nMarkets & Bazaars - Shopping delights of Agra.\nOvernight stay at a hotel in Agra.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Delhi", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "ba22510f-7445-f22d-1132-7846b99971d8", "day_number": 4, "day_title": "Agra to Jaipur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, depart for Jaipur. Jaipur also known as Pink City, it fascinates with its royal palaces, famous forts, and colorful markets. Experience the royal glory and cultural prosperity of Rajasthan''s capital.\nUpon arrival and hotel check-in, relax before an evening exploration of Jaipur''s modern attractions:\nStatue Circle - Modern city landmark.\nBirla Auditorium & Planetarium - Celestial insights.\nVidhan Sabha - Seat of legislative assembly.\nBirla Mandir (Laxmi Narayan Temple) - Marble marvel.\nJawahar Kala Kendra - Cultural hub.\nEnjoy a delightful Rajasthani dinner with folk music and dance in a village setting.\nOvernight stay at a hotel in Jaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "17086cd0-7300-3747-c8ff-d65802407480", "day_number": 5, "day_title": "Jaipur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, explore the historic treasures of Jaipur''s old city:\nHawa Mahal - Palace of winds.\nCity Palace - Residence of Jaipur''s royalty.\nJantar Mantar (Observatory) - Architectural astronomical instruments.\nJal Mahal - Palace amidst the lake.\nAmer Fort - Ancient hilltop fortress.\nNahargarh Fort - Guardian fort of Jaipur.\nIn the evening, witness the spectacular Light & Sound show at Amer Fort.\nOvernight stay at a hotel in Jaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "0787d401-26e1-36ab-4073-36145402e515", "day_number": 6, "day_title": "Jaipur Day Trip to Pushkar and Ajmer", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, take a day trip to Ajmer and Pushkar, both important religious sites. Ajmer: A spiritual hub, Ajmer is home to the revered Ajmer Sharif Dargah. Experience the city''s rich religious heritage, bustling markets, and serene Ana Sagar Lake.Pushkar is renowned for its sacred Pushkar Lake and the Brahma Temple, Pushkar is a vibrant pilgrimage site. Enjoy the lively Pushkar Camel Fair and the town''s bohemian vibe.\nDargah of Khwaja Muin-ud-din Chishti in Ajmer - Sacred Sufi shrine.\nBrahma Temple in Pushkar - Holy shrine of Lord Brahma, the creator.\nReturn to Jaipur in the evening and relax at the hotel.\nOvernight stay at a hotel in Jaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Pushkar", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "714422a5-7180-1b64-9dea-d6993391585c", "day_number": 7, "day_title": "Jaipur Departure", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, you will be transferred to Jaipur Railway Station or Airport for your onward journey. (The Tour Ends)", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": false, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location"